let DB,U,UID,CL={qs:[],mat:[],res:[],h:[],d:[],run:null,t:0,nm:{},tt:'',sj:''};
function protectQuizText(area){if(!area)return;for(const type of ['copy','cut','contextmenu','selectstart','dragstart'])area.addEventListener(type,e=>e.preventDefault(),true);area.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&['c','x','a'].includes(e.key.toLowerCase()))e.preventDefault()})}
async function cls(){const el=$('#cl');if(!el)return;try{DB=await claude.use('db');U=await claude.use('user')}catch(e){}
if(!DB||!U){el.innerHTML='<div class="c"><p>Class features need the page opened while signed in to claude.ai. The page owner (or an editor) is the teacher; invited people are students.</p></div>';return}
try{UID=await U.id();CL.t=U.canEdit();const ld=async c=>(await DB.collection(c).get()).docs.map(d=>({id:d.id,...d.data()}));CL.qs=await ld('quizzes');CL.mat=await ld('materials');if(CL.t)CL.res=await ld('results');else{const s=await DB.collection('data/users/'+UID).doc('h').get();CL.h=s.exists?(s.data().atts||[]):[]}}catch(e){el.innerHTML='<div class="c"><p class="er">Could not load class data: '+esc(e.message||e)+'</p></div>';return}
el.onclick=act;paint()}
async function paint(){const el=$('#cl');if(!el)return;let h='';
const bars=l=>l.map(([x,p])=>`<p class="m" style="margin:8px 0 2px">${x}: ${p}%</p><div class="bar2" role="img" aria-label="${x} ${p}%"><i style="width:${p}%"></i></div>`).join('');
if(CL.t){const rows=CL.res.flatMap(r=>(r.atts||[]).map(a=>({u:r.id,...a})));try{CL.nm=await U.profiles([...new Set(rows.map(r=>r.u))])}catch(e){}
const nm=u=>esc((CL.nm[u]&&CL.nm[u].name)||'Student '+u.slice(0,4)),pc=r=>Math.round(100*r.c/r.n),av=f=>{const m={};rows.forEach(r=>{(m[f(r)]=m[f(r)]||[]).push(pc(r))});return Object.entries(m).map(([x,l])=>[x,Math.round(l.reduce((a,b)=>a+b,0)/l.length)])};
h=`<h1>Teacher portal</h1><div class="c"><h2>New quiz</h2><div class="row"><input id="qt" placeholder="Quiz title" value="${esc(CL.tt)}"><input id="qj" placeholder="Subject" value="${esc(CL.sj)}"></div><input id="qq" placeholder="Question" style="width:100%"><div class="row"><input id="o0" placeholder="Option A"><input id="o1" placeholder="Option B"><input id="o2" placeholder="Option C"><input id="o3" placeholder="Option D"></div><div class="row"><label>Correct <select id="qc"><option value="0">A</option><option value="1">B</option><option value="2">C</option><option value="3">D</option></select></label><input id="qp" placeholder="Topic"><input id="qe" placeholder="Explanation (optional)"><button data-a="add">Add question</button></div><p class="m">${CL.d.length} question(s) in this draft</p><button class="p" data-a="pub">Publish quiz</button></div>
<div class="c" style="margin-top:12px"><h2>Learning material</h2><div class="row"><input id="mt" placeholder="Title"></div><textarea id="mb" rows="4" style="width:100%" placeholder="Notes for students"></textarea><button class="p" data-a="mat">Publish material</button>${CL.mat.map(m=>`<p>${esc(m.title)} <button data-a="dm" data-id="${m.id}">Delete</button></p>`).join('')}</div>
<div class="c" style="margin-top:12px"><h2>Published quizzes</h2>${CL.qs.length?CL.qs.map(q=>`<p>${esc(q.title)} (${q.qs.length} questions) <button data-a="dq" data-id="${q.id}">Delete</button></p>`).join(''):'<p class="m">None yet.</p>'}</div>
<div class="c" style="margin-top:12px"><h2>Student results</h2>${rows.length?`<table><tr><th>Student</th><th>Quiz</th><th>Score</th></tr>${rows.map(r=>`<tr><td>${nm(r.u)}</td><td>${esc(r.title)}</td><td>${r.c}/${r.n} (${pc(r)}%)</td></tr>`).join('')}</table><h3 style="margin-top:14px">Average by student</h3>${bars(av(r=>nm(r.u)))}<h3 style="margin-top:14px">Average by quiz</h3>${bars(av(r=>esc(r.title)))}`:'<p class="m">No student has submitted a quiz yet.</p>'}</div>`}
else if(CL.run){const r=CL.run,q=r.q;h=`<div class="quiz-active"><h1>${esc(q.title)}</h1>${q.qs.map((x,i)=>`<div class="c" style="margin-bottom:8px"><b>${i+1}. ${esc(x.q)}</b>${x.o.map((o,j)=>`<button class="opt" aria-pressed="${r.a[i]===j}" data-a="pick" data-i="${i}" data-j="${j}">${esc(o)}</button>`).join('')}</div>`).join('')}<button class="p" data-a="sub">Submit</button> <button data-a="back">Cancel</button></div>`}
else{h=`<h1>Student area</h1>${CL.msg?`<div class="c"><p>${CL.msg}</p></div>`:''}<div class="c" style="margin-top:12px"><h2>Material</h2>${CL.mat.length?CL.mat.map(m=>`<details><summary>${esc(m.title)}</summary><p style="white-space:pre-wrap">${esc(m.body)}</p></details>`).join(''):'<p class="m">Your teacher has not added material yet.</p>'}</div><div class="c" style="margin-top:12px"><h2>Quizzes</h2>${CL.qs.length?CL.qs.map(q=>`<p>${esc(q.title)} (${q.qs.length}) <button class="p" data-a="start" data-id="${q.id}">Start</button></p>`).join(''):'<p class="m">No quizzes published yet.</p>'}</div><div class="c" style="margin-top:12px"><h2>My results</h2>${CL.h.length?`<table>${CL.h.map(a=>`<tr><td>${esc(a.title)}</td><td>${a.c}/${a.n}</td></tr>`).join('')}</table>`:'<p class="m">No attempts yet.</p>'}</div>`}
el.innerHTML=h;if(CL.run)protectQuizText(el.querySelector('.quiz-active'))}
async function act(e){const b=e.target.closest('[data-a]');if(!b)return;const a=b.dataset.a,v=i=>($('#'+i)||{value:''}).value.trim(),id=b.dataset.id;try{
if(a=='add'){const o=[0,1,2,3].map(i=>v('o'+i));CL.tt=v('qt');CL.sj=v('qj');if(!v('qq')||o.some(x=>!x))return alert('Enter the question and all four options.');CL.d.push({q:v('qq'),o,a:+v('qc'),t:v('qp')||'General',e:v('qe')});paint()}
else if(a=='pub'){CL.tt=v('qt');CL.sj=v('qj');if(!CL.tt||!CL.d.length)return alert('Add a title and at least one question.');const k='q'+Date.now();const doc={title:CL.tt,subject:CL.sj,qs:CL.d};await DB.collection('quizzes').doc(k).set(doc);CL.qs.push({id:k,...doc});CL.d=[];CL.tt='';CL.sj='';paint()}
else if(a=='mat'){if(!v('mt')||!v('mb'))return;const k='m'+Date.now(),doc={title:v('mt'),body:$('#mb').value};await DB.collection('materials').doc(k).set(doc);CL.mat.push({id:k,...doc});paint()}
else if(a=='dq'&&confirm('Delete this quiz?')){await DB.collection('quizzes').doc(id).delete();CL.qs=CL.qs.filter(x=>x.id!=id);paint()}
else if(a=='dm'&&confirm('Delete this material?')){await DB.collection('materials').doc(id).delete();CL.mat=CL.mat.filter(x=>x.id!=id);paint()}
else if(a=='start'){CL.msg='';CL.run={q:CL.qs.find(x=>x.id==id),a:[]};paint()}
else if(a=='pick'){CL.run.a[+b.dataset.i]=+b.dataset.j;paint()}
else if(a=='back'){CL.run=null;paint()}
else if(a=='sub'){const r=CL.run,n=r.q.qs.length;if(r.a.filter(x=>x!=null).length<n&&!confirm('Some questions are unanswered. Submit anyway?'))return;const tp={};let c=0;r.q.qs.forEach((x,i)=>{const ok=r.a[i]==x.a;c+=ok;tp[x.t]=tp[x.t]||[0,0];tp[x.t][0]+=ok;tp[x.t][1]++});CL.h=[...CL.h,{q:r.q.id,title:r.q.title,c,n,at:Date.now(),tp}];CL.run=null;let sh=1;await DB.collection('data/users/'+UID).doc('h').set({atts:CL.h});try{await DB.collection('results').doc(UID).set({atts:CL.h})}catch(x){sh=0}CL.msg='Score: '+c+'/'+n+' ('+Math.round(100*c/n)+'%). '+(sh?'Your teacher can see this result.':'Saved for you, but it could not be shared with your teacher (Contributor access is needed).');paint()}
}catch(x){alert('Action failed: '+(x.message||x))}}
